export default function build({ THREE, traits, ui, isGrabbed, assets }) {
  const root = new THREE.Group();

  const flower = assets.get('flower-trellis');
  root.add(flower.object3D);
  flower.object3D.scale.setScalar(2.2);

  const steps = [
    { id: null, title: 'Parts of a flower', body: 'A flower is the plant\'s reproductive organ. Press Next, or poke a part of the flower, to learn what each part does.' },
    { id: 'petal', title: 'Petal', body: 'Petals are often brightly colored or scented. They attract pollinators such as bees, butterflies and birds.' },
    { id: 'sepal', title: 'Sepal', body: 'Sepals are the small green leaf-like parts under the petals. They enclose and protect the flower bud before it opens.' },
    { id: 'stamen', title: 'Stamen (male part)', body: 'The stamen has an anther on a thin filament. The anther makes pollen, which holds the male cells.' },
    { id: 'pistil', title: 'Pistil (female part)', body: 'The pistil has a sticky stigma that catches pollen, a style, and an ovary. Ovules in the ovary become seeds after fertilization.' },
    { id: 'stem', title: 'Stem', body: 'The stem holds the flower up toward light and pollinators. It carries water and nutrients from the roots to the flower.' },
  ];
  const ids = ['petal', 'sepal', 'stamen', 'pistil', 'stem'];
  const names = { petal: 'Petal', sepal: 'Sepal', stamen: 'Stamen', pistil: 'Pistil', stem: 'Stem' };

  const labels = {};
  ids.forEach((id) => { labels[id] = flower.label(id, names[id]); });

  const panel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .step { color: #8fb4ff; font-size: 20px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #dfe3ea; font-size: 24px; }
      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
              border-radius: 12px; background-color: #3a4049; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
      .credit { color: #9aa1ac; font-size: 18px; }
    </style>
    <div class="card">
      <span class="step" id="step">Overview</span>
      <span class="title" id="title">Parts of a flower</span>
      <span class="body" id="body">x</span>
      <div class="row">
        <button class="btn" id="prev"><span class="bt">Back</span></button>
        <button class="btn" id="next"><span class="bt">Next</span></button>
      </div>
      <div class="row">
        <button class="btn2" id="explode"><span class="bt" id="explodeT">Explode</span></button>
        <button class="btn2" id="xray"><span class="bt" id="xrayT">X-ray</span></button>
        <button class="btn2" id="reset"><span class="bt">Reset</span></button>
      </div>
      <span class="credit">${flower.credit || 'Model: TRELLIS.2 (generated)'}</span>
    </div>`, { width: 0.42, position: [0, 0.38, 0] });
  root.add(panel.object3D);

  let step = 0;
  let exploded = false;
  let xrayOn = false;
  let explodeAmt = 0;

  function apply() {
    const s = steps[step];
    panel.set('step', { text: step === 0 ? 'Overview' : 'Part ' + step + ' of ' + ids.length });
    panel.set('title', { text: s.title });
    panel.set('body', { text: s.body });
    ids.forEach((id) => labels[id].setVisible(s.id === null || s.id === id));
    flower.highlight(s.id);
    if (xrayOn) flower.xray(true, s.id ? [s.id] : ids);
    else flower.xray(false);
    panel.set('explodeT', { text: exploded ? 'Assemble' : 'Explode' });
    panel.set('xrayT', { text: xrayOn ? 'Solid' : 'X-ray' });
  }

  panel.on('next', 'click', () => { step = (step + 1) % steps.length; apply(); });
  panel.on('prev', 'click', () => { step = (step + steps.length - 1) % steps.length; apply(); });
  panel.on('explode', 'click', () => { exploded = !exploded; apply(); });
  panel.on('xray', 'click', () => { xrayOn = !xrayOn; apply(); });
  panel.on('reset', 'click', () => {
    step = 0; exploded = false; xrayOn = false; explodeAmt = 0;
    flower.reset();
    apply();
  });

  ids.forEach((id) => {
    const p = flower.part(id);
    if (p) {
      traits(p, {
        grab: true,
        onPress: () => { step = ids.indexOf(id) + 1; apply(); },
      });
    }
  });

  apply();

  return {
    root,
    update(time, delta) {
      const target = exploded ? 0.7 : 0;
      explodeAmt += (target - explodeAmt) * Math.min(1, delta * 3);
      flower.explode(explodeAmt);
    },
  };
}
